.component-{{id}}.floating-content {
  animation: floating-content-{{id}} var(--floating-duration, 6s) ease-in-out infinite;
  animation-play-state: var(--floating-play-state, running);
  will-change: transform;
}

@keyframes floating-content-{{id}} {
  0%, 100% { transform: translate3d(0, 0, 0) rotate(var(--floating-twist-start, 0deg)); }
  50% { transform: translate3d(0, calc(-1 * var(--floating-drift, 8px)), 0) rotate(var(--floating-twist-end, 0deg)); }
}

@media (prefers-reduced-motion: reduce) {
  .component-{{id}}.floating-content {
    animation: none;
  }
}

const transformHook = (rw) => {
  const props = rw.props || {};
  const numberInRange = (value, fallback, min, max) => {
    const parsed = Number(value);
    return Number.isFinite(parsed) ? Math.min(max, Math.max(min, parsed)) : fallback;
  };

  const duration = numberInRange(props.duration, 6, 2, 16);
  const drift = numberInRange(props.drift, 8, 0, 32);
  const twistEnabled = props.twistEnabled === "enabled";
  const playState = props.playState === "paused" ? "paused" : "running";

  rw.setProps({
    floatingDuration: `${duration}s`,
    floatingDrift: `${drift}px`,
    floatingTwistStart: twistEnabled ? "1deg" : "0deg",
    floatingTwistEnd: twistEnabled ? "-1deg" : "0deg",
    floatingPlayState: playState
  });
};

exports.transformHook = transformHook;

{
  "groups": [
    {
      "title": "Animation",
      "icon": "wind",
      "properties": [
        {
          "title": "Animate",
          "id": "playState",
          "responsive": false,
          "switch": {
            "default": true,
            "trueValue": "running",
            "falseValue": "paused"
          }
        },
        {
          "title": "Speed",
          "id": "duration",
          "responsive": false,
          "slider": {
            "default": 6,
            "min": 2,
            "max": 16,
            "step": 1,
            "units": "sec",
            "round": true
          }
        },
        {
          "title": "Vertical Drift",
          "id": "drift",
          "responsive": false,
          "slider": {
            "default": 8,
            "min": 0,
            "max": 32,
            "step": 1,
            "units": "px",
            "round": true
          }
        },
        {
          "title": "Twist",
          "id": "twistEnabled",
          "responsive": false,
          "switch": {
            "default": true,
            "trueValue": "enabled",
            "falseValue": "disabled"
          }
        }
      ]
    }
  ]
}

/* ── Status Dot ─────────────────────────────────────────── */
/* Scoped by the static .status-dot class. Per-instance {{id}}
   interpolation is unreliable in preview/publish builds, so the size
   is passed as an inline --dot-size variable from the template. */

.status-dot {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: var(--dot-size, 8px);
  height: var(--dot-size, 8px);
  flex-shrink: 0;
}

/* Solid core dot */
.status-dot .status-dot__core {
  position: relative;
  z-index: 1;
  width: 100%;
  height: 100%;
  border-radius: 9999px;
}

/* Expanding/fading ring */
.status-dot .status-dot__ring {
  position: absolute;
  inset: 0;
  border-radius: 9999px;
  opacity: 0.6;
  animation: status-dot-pulse 2s cubic-bezier(0.4, 0, 0.6, 1) infinite;
}

@keyframes status-dot-pulse {
  0%, 100% {
    transform: scale(1);
    opacity: 0.6;
  }
  50% {
    transform: scale(2.2);
    opacity: 0;
  }
}

@media (prefers-reduced-motion: reduce) {
  .status-dot .status-dot__ring {
    animation: none;
  }
}

{
  "groups": [
    {
      "title": "Status Dot",
      "icon": "circle.fill",
      "properties": [
        {
          "title": "Dot Colour",
          "id": "dotColor",
          "responsive": false,
          "format": "bg-{{value}}",
          "themeColor": {
            "mode": "single",
            "default": {
              "name": "emerald",
              "brightness": 500
            }
          }
        },
        {
          "title": "Size",
          "id": "dotSize",
          "responsive": false,
          "number": {
            "default": 8,
            "min": 6,
            "max": 24,
            "step": 1,
            "round": true,
            "subtitle": "Diameter in pixels"
          }
        }
      ]
    }
  ]
}

